from jsonb_to_recordset('[{"id":"mc-es-001","mode":"mc","category":"España cañí","difficulty":"easy","question":"¿Qué ciudad fue capital del reino visigodo en la península?","answer":"Toledo","options":["Toledo","Sevilla","Mérida","León"],"unit":null,"tolerance":0,"explanation":"Toledo fue el principal centro político visigodo desde el siglo VI.","source":"Real Academia de la Historia · Diccionario Biográfico"},{"id":"mc-es-002","mode":"mc","category":"España cañí","difficulty":"normal","question":"¿Qué comunidad autónoma tiene más provincias?","answer":"Castilla y León","options":["Castilla y León","Andalucía","Castilla-La Mancha","Aragón"],"unit":null,"tolerance":0,"explanation":"Castilla y León está formada por nueve provincias.","source":"Instituto Geográfico Nacional · España en mapas"},{"id":"mc-world-001","mode":"mc","category":"Curiosidades absurdas","difficulty":"easy","question":"¿Cuál es el único mamífero capaz de volar activamente?","answer":"El murciélago","options":["El murciélago","La ardilla voladora","El petauro del azúcar","El colugo"],"unit":null,"tolerance":0,"explanation":"Otros mamíferos planean, pero los murciélagos generan vuelo propulsado.","source":"Smithsonian National Zoo · Bats"},{"id":"mc-es-003","mode":"mc","category":"España cañí","difficulty":"normal","question":"¿Qué monarca español recibió el sobrenombre de «el Hechizado»?","answer":"Carlos II","options":["Carlos II","Felipe IV","Carlos III","Fernando VII"],"unit":null,"tolerance":0,"explanation":"El apodo se popularizó en torno a Carlos II, último Austria español.","source":"Museo del Prado · Carlos II"},{"id":"mc-es-004","mode":"mc","category":"Comida y bebida","difficulty":"normal","question":"¿Qué fruto seco caracteriza la picada de una salsa romesco tradicional?","answer":"La almendra","options":["La almendra","El anacardo","El pistacho","La nuez pecana"],"unit":null,"tolerance":0,"explanation":"Almendras y avellanas tostadas aportan cuerpo a la salsa romesco.","source":"Corpus de la cuina catalana · Romesco"},{"id":"mc-es-005","mode":"mc","category":"Cultura general","difficulty":"easy","question":"¿En qué año dejó la peseta de ser moneda de curso legal en España?","answer":"2002","options":["1999","2000","2002","2004"],"unit":null,"tolerance":0,"explanation":"El euro en efectivo llegó el 1 de enero de 2002; la peseta dejó de ser de curso legal el 28 de febrero.","source":"Banco de España · El euro"},{"id":"mc-es-006","mode":"mc","category":"España cañí","difficulty":"difficult","question":"¿Qué provincia gallega limita al norte con el Cantábrico y al oeste con A Coruña?","answer":"Lugo","options":["Ourense","Asturias","Lugo","Pontevedra"],"unit":null,"tolerance":0,"explanation":"Lugo ocupa el extremo nororiental de Galicia; su costa norte se asoma al Cantábrico.","source":"Xunta de Galicia · Enciclopedia Galega Universal, «Lugo, provincia de»"},{"id":"mc-world-002","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Qué país europeo tiene más kilómetros de costa si se cuentan sus islas?","answer":"Noruega","options":["Noruega","Grecia","Italia","Reino Unido"],"unit":null,"tolerance":0,"explanation":"La costa noruega se alarga enormemente al incluir fiordos e islas.","source":"CIA World Factbook · Coastline"},{"id":"mc-es-007","mode":"mc","category":"Cultura general","difficulty":"easy","question":"¿En qué año se inauguró el Museo del Prado?","answer":"1819","options":["1785","1819","1868","1898"],"unit":null,"tolerance":0,"explanation":"El Real Museo de Pintura abrió sus puertas el 19 de noviembre de 1819.","source":"Museo Nacional del Prado · Historia"},{"id":"mc-es-008","mode":"mc","category":"Cine y series","difficulty":"normal","question":"¿Qué película de Pedro Almodóvar ganó el Óscar a mejor película internacional en 2000?","answer":"Todo sobre mi madre","options":["Todo sobre mi madre","Hable con ella","Volver","Mujeres al borde de un ataque de nervios"],"unit":null,"tolerance":0,"explanation":"La película recibió el premio en la ceremonia de 2000.","source":"Academy of Motion Picture Arts and Sciences · Awards"},{"id":"mc-es-009","mode":"mc","category":"Cultura general","difficulty":"easy","question":"¿Quién escribió «Nada», novela ganadora del primer premio Nadal?","answer":"Carmen Laforet","options":["Carmen Laforet","Ana María Matute","Carmen Martín Gaite","Mercè Rodoreda"],"unit":null,"tolerance":0,"explanation":"Laforet ganó la primera edición del Nadal, publicada en 1945.","source":"Editorial Destino · Premio Nadal"},{"id":"mc-world-003","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Qué elemento químico tiene el símbolo W?","answer":"Wolframio","options":["Wolframio","Vanadio","Tungsteno","Wolframio y tungsteno son nombres del mismo elemento"],"unit":null,"tolerance":0,"explanation":"W procede de wolfram; tungsteno es otro nombre aceptado del elemento 74.","source":"IUPAC · Periodic Table"},{"id":"mc-es-010","mode":"mc","category":"Música y canciones","difficulty":"normal","question":"¿Qué grupo publicó el álbum «Un día en el mundo» en 2008?","answer":"Vetusta Morla","options":["Vetusta Morla","Love of Lesbian","Izal","Supersubmarina"],"unit":null,"tolerance":0,"explanation":"Fue el álbum de debut de larga duración de la banda madrileña.","source":"Vetusta Morla · Discografía oficial"},{"id":"mc-world-004","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"En la mitología griega, ¿quién robó el fuego para entregárselo a la humanidad?","answer":"Prometeo","options":["Prometeo","Hermes","Dédalo","Orfeo"],"unit":null,"tolerance":0,"explanation":"Zeus castigó a Prometeo por entregar el fuego a los mortales.","source":"Theoi Greek Mythology · Prometheus"},{"id":"mc-es-011","mode":"mc","category":"España cañí","difficulty":"normal","question":"¿Qué río atraviesa Zaragoza?","answer":"El Ebro","options":["El Ebro","El Jalón","El Gállego","El Segre"],"unit":null,"tolerance":0,"explanation":"Zaragoza se asienta junto al Ebro, cerca de la desembocadura del Gállego.","source":"Confederación Hidrográfica del Ebro"},{"id":"mc-world-005","mode":"mc","category":"Fútbol y deportes","difficulty":"easy","question":"¿Qué selección ganó el Mundial masculino de fútbol de 2010?","answer":"España","options":["España","Países Bajos","Alemania","Uruguay"],"unit":null,"tolerance":0,"explanation":"España venció a Países Bajos 1-0 en la final de Johannesburgo.","source":"FIFA · World Cup 2010"},{"id":"mc-es-012","mode":"mc","category":"España cañí","difficulty":"difficult","question":"¿Qué tratado de 1713 cedió Gibraltar a Gran Bretaña?","answer":"Tratado de Utrecht","options":["Tratado de Utrecht","Tratado de Rastatt","Tratado de Fontainebleau","Paz de Westfalia"],"unit":null,"tolerance":0,"explanation":"El artículo X del Tratado de Utrecht formalizó la cesión.","source":"Archivo Histórico Nacional · Tratado de Utrecht"},{"id":"mc-world-006","mode":"mc","category":"Internet y memes","difficulty":"normal","question":"¿Qué plataforma lanzó originalmente el formato de vídeo corto «Vine»?","answer":"Twitter","options":["Twitter","Meta","Google","Snap"],"unit":null,"tolerance":0,"explanation":"Twitter adquirió Vine en 2012; la aplicación se lanzó en 2013.","source":"Twitter Blog · Introducing Vine (2013)"},{"id":"mc-es-013","mode":"mc","category":"Marcas y publicidad","difficulty":"normal","question":"¿En qué ciudad nació Inditex?","answer":"Arteixo","options":["Arteixo","A Coruña","Vigo","Ourense"],"unit":null,"tolerance":0,"explanation":"La sede corporativa del grupo está en Arteixo, Galicia.","source":"Inditex · Información corporativa"},{"id":"mc-world-007","mode":"mc","category":"Videojuegos y dibujos","difficulty":"easy","question":"¿Qué estudio desarrolló «The Last of Us»?","answer":"Naughty Dog","options":["Naughty Dog","Insomniac Games","Bungie","Santa Monica Studio"],"unit":null,"tolerance":0,"explanation":"El juego se publicó en 2013 para PlayStation 3.","source":"PlayStation · The Last of Us"},{"id":"mc-es-014","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Qué científico español recibió el Nobel de Medicina en 1959?","answer":"Severo Ochoa","options":["Severo Ochoa","Santiago Ramón y Cajal","Margarita Salas","Juan de la Cierva"],"unit":null,"tolerance":0,"explanation":"Ochoa compartió el Nobel por sus descubrimientos sobre la síntesis biológica de ARN y ADN.","source":"Nobel Prize · Severo Ochoa"},{"id":"mc-world-008","mode":"mc","category":"Cultura general","difficulty":"easy","question":"¿En qué año cayó el Muro de Berlín?","answer":"1989","options":["1985","1989","1991","1993"],"unit":null,"tolerance":0,"explanation":"La apertura de los pasos fronterizos se produjo el 9 de noviembre de 1989.","source":"German Historical Museum · Fall of the Wall"},{"id":"mc-es-015","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿Quién diseñó el Palacio de Cristal del Retiro de Madrid?","answer":"Ricardo Velázquez Bosco","options":["Ricardo Velázquez Bosco","Antonio Palacios","Juan de Villanueva","Secundino Zuazo"],"unit":null,"tolerance":0,"explanation":"Se construyó en 1887 para la Exposición de Filipinas.","source":"Museo Reina Sofía · Palacio de Cristal"},{"id":"mc-world-009","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Cuál es el animal terrestre más rápido en distancias cortas?","answer":"El guepardo","options":["El guepardo","El antílope americano","El león","El avestruz"],"unit":null,"tolerance":0,"explanation":"El guepardo puede alcanzar velocidades muy altas durante aceleraciones breves.","source":"Smithsonian National Zoo · Cheetah"},{"id":"mc-es-016","mode":"mc","category":"Comida y bebida","difficulty":"normal","question":"¿Qué ingrediente da el color amarillo tradicional a la fabada asturiana?","answer":"Azafrán","options":["Azafrán","Pimentón dulce","Cúrcuma","Colorante de achiote"],"unit":null,"tolerance":0,"explanation":"Algunas recetas tradicionales añaden unas hebras de azafrán.","source":"Consejo Regulador IGP Faba Asturiana"},{"id":"mc-world-010","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿Quién escribió «Cien años de soledad»?","answer":"Gabriel García Márquez","options":["Gabriel García Márquez","Mario Vargas Llosa","Julio Cortázar","Juan Rulfo"],"unit":null,"tolerance":0,"explanation":"La novela se publicó en 1967 y es una obra clave del realismo mágico.","source":"Fundación Gabo · Obra"},{"id":"mc-es-017","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿Qué cámara de las Cortes Generales representa territorialmente a España?","answer":"El Senado","options":["El Senado","El Congreso","El Consejo de Estado","El Tribunal Constitucional"],"unit":null,"tolerance":0,"explanation":"La Constitución define el Senado como cámara de representación territorial.","source":"Constitución Española · Artículo 69"},{"id":"mc-world-011","mode":"mc","category":"Curiosidades absurdas","difficulty":"easy","question":"¿Qué planeta del sistema solar tiene el día más largo que su año?","answer":"Venus","options":["Venus","Marte","Mercurio","Neptuno"],"unit":null,"tolerance":0,"explanation":"Venus tarda más en rotar sobre su eje que en completar su órbita alrededor del Sol.","source":"NASA Solar System Exploration · Venus"},{"id":"mc-es-018","mode":"mc","category":"Fútbol y deportes","difficulty":"normal","question":"¿Qué tenista español ganó Roland Garros por primera vez en 2005?","answer":"Rafael Nadal","options":["Rafael Nadal","Carlos Moyá","David Ferrer","Juan Carlos Ferrero"],"unit":null,"tolerance":0,"explanation":"Nadal ganó su primer Roland Garros con 19 años.","source":"Roland-Garros · Palmarès"},{"id":"mc-world-012","mode":"mc","category":"Cultura general","difficulty":"difficult","question":"¿Qué organización publica el informe «Perspectivas de la economía mundial»?","answer":"Fondo Monetario Internacional","options":["Fondo Monetario Internacional","Banco Mundial","OCDE","Banco Central Europeo"],"unit":null,"tolerance":0,"explanation":"El FMI publica el World Economic Outlook con periodicidad semestral.","source":"IMF · World Economic Outlook"},{"id":"mc-es-019","mode":"mc","category":"Música y canciones","difficulty":"difficult","question":"¿Qué compositor creó la suite «Iberia» para piano?","answer":"Isaac Albéniz","options":["Isaac Albéniz","Enrique Granados","Manuel de Falla","Joaquín Turina"],"unit":null,"tolerance":0,"explanation":"Iberia, compuesta entre 1905 y 1908, reúne doce piezas para piano.","source":"Fundación Albéniz · Isaac Albéniz"},{"id":"mc-world-013","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Qué científica acuñó el término «radioactividad»?","answer":"Marie Curie","options":["Marie Curie","Lise Meitner","Irène Joliot-Curie","Rosalind Franklin"],"unit":null,"tolerance":0,"explanation":"Marie Curie introdujo el término mientras investigaba los rayos del uranio.","source":"Nobel Prize · Marie Curie"},{"id":"mc-es-020","mode":"mc","category":"España cañí","difficulty":"difficult","question":"¿Qué ciudad fue sede de las primeras Cortes de León de 1188?","answer":"León","options":["León","Burgos","Oviedo","Salamanca"],"unit":null,"tolerance":0,"explanation":"Las Cortes de León de 1188 son reconocidas por la UNESCO como testimonio temprano del parlamentarismo.","source":"UNESCO Memory of the World · Decreta of León"},{"id":"mc-world-014","mode":"mc","category":"Cine y series","difficulty":"normal","question":"¿Qué director filmó «Parásitos»?","answer":"Bong Joon-ho","options":["Bong Joon-ho","Park Chan-wook","Lee Chang-dong","Kim Ki-duk"],"unit":null,"tolerance":0,"explanation":"Fue la primera película en lengua no inglesa en ganar el Óscar a mejor película.","source":"Academy Awards · Parasite"},{"id":"mc-es-021","mode":"mc","category":"España cañí","difficulty":"difficult","question":"¿Cuál es el pico más alto de los Pirineos?","answer":"Aneto","options":["Aneto","Posets","Monte Perdido","Vignemale"],"unit":null,"tolerance":0,"explanation":"El Aneto alcanza 3.404 metros en el macizo de la Maladeta.","source":"Instituto Geográfico Nacional · Anuario geográfico"},{"id":"mc-world-015","mode":"mc","category":"Marcas y publicidad","difficulty":"normal","question":"¿En qué país se fundó IKEA?","answer":"Suecia","options":["Suecia","Dinamarca","Noruega","Países Bajos"],"unit":null,"tolerance":0,"explanation":"Ingvar Kamprad fundó IKEA en Älmhult en 1943.","source":"IKEA Museum · Our history"},{"id":"mc-es-022","mode":"mc","category":"Cine y series","difficulty":"difficult","question":"¿Qué película española ganó el Óscar a mejor película de habla no inglesa en 1994?","answer":"Belle Époque","options":["Belle Époque","Jamón, jamón","La ardilla roja","El día de la bestia"],"unit":null,"tolerance":0,"explanation":"La película de Fernando Trueba ganó en la ceremonia de 1994.","source":"Academy Awards · Belle Époque"},{"id":"mc-world-016","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Qué estrecho separa Asia de América del Norte?","answer":"Estrecho de Bering","options":["Estrecho de Bering","Estrecho de Malaca","Estrecho de Davis","Estrecho de Torres"],"unit":null,"tolerance":0,"explanation":"El estrecho de Bering separa Siberia de Alaska.","source":"National Geographic · Bering Strait"},{"id":"mc-es-023","mode":"mc","category":"Cultura general","difficulty":"easy","question":"¿Cuántos miembros tiene el Congreso de los Diputados español?","answer":"350","options":["300","350","400","450"],"unit":null,"tolerance":0,"explanation":"La Constitución fija un rango de 300 a 400; la ley electoral establece 350.","source":"Congreso de los Diputados · Composición"},{"id":"mc-world-017","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿Qué imperio construyó Machu Picchu?","answer":"El inca","options":["El inca","El maya","El mexica","El wari"],"unit":null,"tolerance":0,"explanation":"La ciudadela se levantó en el siglo XV durante el apogeo inca.","source":"UNESCO World Heritage · Historic Sanctuary of Machu Picchu"},{"id":"mc-es-024","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿En qué localidad nació Federico García Lorca?","answer":"Fuente Vaqueros","options":["Fuente Vaqueros","Granada","Valderrubio","Alfacar"],"unit":null,"tolerance":0,"explanation":"Nació en Fuente Vaqueros, provincia de Granada, en 1898.","source":"Fundación Federico García Lorca · Biografía"},{"id":"mc-world-018","mode":"mc","category":"Videojuegos y dibujos","difficulty":"normal","question":"¿Cuál fue la primera consola doméstica de Nintendo?","answer":"Color TV-Game","options":["Color TV-Game","Famicom","Game Boy","Nintendo 64"],"unit":null,"tolerance":0,"explanation":"Nintendo lanzó la serie Color TV-Game en Japón a partir de 1977.","source":"Nintendo · Historia corporativa"},{"id":"mc-es-025","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Qué árbol es el emblema vegetal de la Comunidad de Madrid?","answer":"La encina","options":["La encina","El olivo","El madroño","El alcornoque"],"unit":null,"tolerance":0,"explanation":"La bandera madrileña muestra siete estrellas sobre fondo rojo; el madroño aparece en el escudo de la capital.","source":"Comunidad de Madrid · Símbolos"},{"id":"mc-world-019","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿En qué museo se encuentra actualmente «La noche estrellada» de Van Gogh?","answer":"MoMA, Nueva York","options":["MoMA, Nueva York","Rijksmuseum, Ámsterdam","Museo de Orsay, París","Tate Modern, Londres"],"unit":null,"tolerance":0,"explanation":"La obra de 1889 forma parte de la colección del Museum of Modern Art.","source":"MoMA · The Starry Night"},{"id":"mc-es-026","mode":"mc","category":"España cañí","difficulty":"easy","question":"¿Qué expedición completó la primera vuelta al mundo?","answer":"Magallanes-Elcano","options":["Magallanes-Elcano","Colón-Vespucci","Balboa-Pizarro","Cortés-Orellana"],"unit":null,"tolerance":0,"explanation":"La expedición partió en 1519 y regresó en 1522 bajo el mando de Juan Sebastián Elcano.","source":"Museo Naval · Primera vuelta al mundo"},{"id":"mc-world-020","mode":"mc","category":"Curiosidades absurdas","difficulty":"difficult","question":"¿Qué unidad del SI mide la actividad catalítica?","answer":"Katal","options":["Katal","Sievert","Gray","Weber"],"unit":null,"tolerance":0,"explanation":"El katal (kat) equivale a un mol de sustrato transformado por segundo.","source":"BIPM · SI Brochure"},{"id":"mc-es-027","mode":"mc","category":"Comida y bebida","difficulty":"easy","question":"¿De qué región española es originaria la torta del Casar?","answer":"Extremadura","options":["Extremadura","Castilla-La Mancha","Andalucía","Galicia"],"unit":null,"tolerance":0,"explanation":"La DOP ampara este queso elaborado en la provincia de Cáceres.","source":"Consejo Regulador DOP Torta del Casar"},{"id":"mc-world-021","mode":"mc","category":"Curiosidades absurdas","difficulty":"difficult","question":"¿Qué ave mitológica renace de sus cenizas?","answer":"El fénix","options":["El fénix","El grifo","El roc","El hipogrifo"],"unit":null,"tolerance":0,"explanation":"El fénix aparece en tradiciones antiguas de Egipto, Grecia y Roma.","source":"Encyclopaedia Britannica · Phoenix"},{"id":"mc-es-028","mode":"mc","category":"Fútbol y deportes","difficulty":"normal","question":"¿Qué equipo ganó la primera edición de la Liga española de fútbol, en 1929?","answer":"FC Barcelona","options":["FC Barcelona","Real Madrid","Athletic Club","Real Sociedad"],"unit":null,"tolerance":0,"explanation":"El Barcelona terminó primero en la temporada inaugural 1928-29.","source":"LaLiga · Historia"},{"id":"mc-world-022","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿En qué ciudad está la sede principal de la Organización Mundial de la Salud?","answer":"Ginebra","options":["Ginebra","Nueva York","Viena","La Haya"],"unit":null,"tolerance":0,"explanation":"La sede de la OMS está en Ginebra, Suiza.","source":"World Health Organization · Contact"},{"id":"mc-es-029","mode":"mc","category":"España cañí","difficulty":"normal","question":"¿Qué batalla de 1212 marcó una gran victoria cristiana durante la Reconquista?","answer":"Las Navas de Tolosa","options":["Las Navas de Tolosa","Alarcos","Roncesvalles","Muret"],"unit":null,"tolerance":0,"explanation":"La coalición cristiana derrotó al ejército almohade en Sierra Morena.","source":"Real Academia de la Historia · Navas de Tolosa"},{"id":"mc-world-023","mode":"mc","category":"Curiosidades absurdas","difficulty":"easy","question":"¿Qué gas constituye la mayor parte de la atmósfera terrestre?","answer":"Nitrógeno","options":["Nitrógeno","Oxígeno","Argón","Dióxido de carbono"],"unit":null,"tolerance":0,"explanation":"El nitrógeno representa cerca del 78 % del aire seco.","source":"NASA Earth Observatory · The Atmosphere"},{"id":"mc-es-030","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿En qué ciudad está el conjunto monumental de la Alhambra?","answer":"Granada","options":["Granada","Córdoba","Sevilla","Málaga"],"unit":null,"tolerance":0,"explanation":"La Alhambra fue ciudad palatina nazarí y es Patrimonio Mundial.","source":"UNESCO World Heritage · Alhambra"},{"id":"mc-world-024","mode":"mc","category":"Cultura general","difficulty":"difficult","question":"¿Qué tratado puso fin oficialmente a la Primera Guerra Mundial entre Alemania y los Aliados?","answer":"Tratado de Versalles","options":["Tratado de Versalles","Tratado de Trianon","Tratado de Brest-Litovsk","Tratado de Lausana"],"unit":null,"tolerance":0,"explanation":"Se firmó el 28 de junio de 1919.","source":"National Archives UK · Treaty of Versailles"},{"id":"mc-es-031","mode":"mc","category":"Internet y memes","difficulty":"normal","question":"¿Qué ciudad española acoge el evento de videojuegos DreamHack Valencia?","answer":"Valencia","options":["Valencia","Barcelona","Madrid","Málaga"],"unit":null,"tolerance":0,"explanation":"La edición española del festival se celebra en Feria Valencia.","source":"DreamHack España · Valencia"},{"id":"mc-world-025","mode":"mc","category":"Comida y bebida","difficulty":"normal","question":"¿Qué ingrediente principal lleva el hummus clásico?","answer":"Garbanzos","options":["Garbanzos","Lentejas","Alubias blancas","Berenjena"],"unit":null,"tolerance":0,"explanation":"El hummus tradicional se prepara con garbanzos, tahini, limón y ajo.","source":"Encyclopaedia Britannica · Hummus"},{"id":"mc-es-032","mode":"mc","category":"España cañí","difficulty":"normal","question":"¿Qué isla canaria alberga el Parque Nacional del Teide?","answer":"Tenerife","options":["Tenerife","Gran Canaria","La Palma","La Gomera"],"unit":null,"tolerance":0,"explanation":"El parque ocupa el centro de Tenerife y contiene el pico más alto de España.","source":"Parques Nacionales · Teide"},{"id":"mc-world-026","mode":"mc","category":"Curiosidades absurdas","difficulty":"normal","question":"¿Quién patentó el teléfono en Estados Unidos en 1876?","answer":"Alexander Graham Bell","options":["Alexander Graham Bell","Thomas Edison","Elisha Gray","Nikola Tesla"],"unit":null,"tolerance":0,"explanation":"Bell recibió la patente estadounidense 174,465 en marzo de 1876.","source":"United States Patent and Trademark Office · Patent 174,465"},{"id":"mc-es-033","mode":"mc","category":"Cultura general","difficulty":"difficult","question":"¿Qué impuesto indirecto armonizado se aplica en España y grava el consumo?","answer":"IVA","options":["IVA","IRPF","Impuesto de sociedades","IBI"],"unit":null,"tolerance":0,"explanation":"El IVA es un impuesto sobre el valor añadido en entregas y servicios.","source":"Agencia Tributaria · IVA"},{"id":"mc-world-027","mode":"mc","category":"Curiosidades absurdas","difficulty":"difficult","question":"¿Qué estructura permite a los tiburones detectar campos eléctricos débiles?","answer":"Ampollas de Lorenzini","options":["Ampollas de Lorenzini","Línea de Weber","Órgano de Jacobson","Órgano de Corti"],"unit":null,"tolerance":0,"explanation":"Estos electrorreceptores se concentran especialmente en la cabeza.","source":"Smithsonian Ocean · Shark senses"},{"id":"mc-es-034","mode":"mc","category":"Música y canciones","difficulty":"easy","question":"¿Qué artista lanzó el álbum «El mal querer» en 2018?","answer":"Rosalía","options":["Rosalía","Bad Gyal","Amaia","Aitana"],"unit":null,"tolerance":0,"explanation":"El álbum conceptual recibió el Latin Grammy a álbum del año.","source":"Latin Recording Academy · El mal querer"},{"id":"mc-world-028","mode":"mc","category":"Marcas y publicidad","difficulty":"difficult","question":"¿Qué empresa creó el lenguaje de programación Java?","answer":"Sun Microsystems","options":["Sun Microsystems","Microsoft","IBM","Oracle"],"unit":null,"tolerance":0,"explanation":"Java fue desarrollado en Sun y anunciado públicamente en 1995.","source":"Oracle · The History of Java"},{"id":"mc-es-035","mode":"mc","category":"Cultura general","difficulty":"normal","question":"¿Qué poeta escribió «Campos de Castilla»?","answer":"Antonio Machado","options":["Antonio Machado","Juan Ramón Jiménez","Miguel Hernández","Luis Cernuda"],"unit":null,"tolerance":0,"explanation":"La colección se publicó en 1912 y retrata paisajes y temas castellanos.","source":"Biblioteca Nacional de España · Antonio Machado"},{"id":"mc-world-029","mode":"mc","category":"Curiosidades absurdas","difficulty":"easy","question":"¿Cuál es la capital de Nueva Zelanda?","answer":"Wellington","options":["Wellington","Auckland","Christchurch","Hamilton"],"unit":null,"tolerance":0,"explanation":"Wellington es la capital desde 1865.","source":"New Zealand Government · Capital city"},{"id":"mc-es-036","mode":"mc","category":"Fútbol y deportes","difficulty":"difficult","question":"¿Qué atleta española ganó el oro olímpico de marcha de